#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// ModalLayer's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/modal_layer.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// Whether Escape inside the layer asks to close it as cancelled (through closing, which may refuse).
template <typename Declaring>
struct ModalLayerCloseOnEscapeCapability {
    PropertyCell<bool, ModalLayerCloseOnEscapeCapability<Declaring>> close_on_escape{true};

    static void assign(ModalLayerCloseOnEscapeCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.close_on_escape), incoming);
        if (!capability.close_on_escape.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.close_on_escape));
    }
};

// Every ModalLayer capability, in the order the declaring class takes them.
template <typename Declaring>
struct ModalLayerCapabilities : public ModalLayerCloseOnEscapeCapability<Declaring> {};

} // namespace gui_forms
